const express = require('express');
const { GitRepository } = require('../models/gitRepository');

const app = express();
const projectRouter = express.Router({ mergeParams: true });

app.use('/orgs/:orgSlug/projects', async (req, res, next) => {
  if (!req.user) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate user organization membership
  const isMember = await req.user.isMemberOfOrg(req.params.orgSlug);
  if (!isMember) {
    return res.status(403).json({ error: 'Forbidden: not an organization member' });
  }
  next();
}, projectRouter);

projectRouter.get('/:projectId/commits', async (req, res) => {
  // Ensure repository matches both the projectId and the mounted orgSlug
  const repository = await GitRepository.findOne({
    _id: req.params.projectId,
    organizationSlug: req.params.orgSlug
  });

  if (!repository) {
    return res.status(404).json({ error: 'Repository not found in this organization' });
  }

  const commits = await repository.getCommitHistory({ limit: 50 });
  res.json({
    projectId: req.params.projectId,
    commits
  });
});

app.listen(4000);
